#include "Rover.h"

int x = 0;  // cells right of the start (left is negative)

// Facing a wall: go to its left end, then right until the way up is open.
void findGap() {
  turnLeft();
  while (distanceAhead() > 0) {
    forward(1);
    x--;
  }
  turnRight();
  while (distanceAhead() == 0) {
    turnRight();
    forward(1);
    x++;
    turnLeft();
  }
}

void setup() {
  forward(1);
  findGap();
  forward(3);
  findGap();
  forward(3);
  int dx = 3 - x;
  if (dx > 0) {
    turnRight();
    forward(dx);
  }
  if (dx < 0) {
    turnLeft();
    forward(-dx);
  }
}

void loop() {
}
